    def get_summary_stock(
        self,
        code: str,
        from_: Union[str, _date],
        to: Union[str, _date],
        investor: SummaryStockInvestor,
        market: SummaryStockMarket,
    ) -> SummaryStockResponse:
        """Stock Broker Summary.
        
        Get detailed trading broker activity analysis for a specific stock within a specific time period.
        
        Response:
        - code: Broker code (2 letters)
        - buy_freq: Total broker buy frequency over the period (numeric string)
        - buy_volume: Total buy volume in shares (numeric string)
        - buy_value: Total buy value in Rupiah (numeric string)
        - sell_freq: Total broker sell frequency over the period (numeric string)
        - sell_volume: Total sell volume in shares (numeric string)
        - sell_value: Total sell value in Rupiah (numeric string)
        - buy_avg: Average buy price in Rupiah (buy_value / buy_volume, decimal string; null when buy_volume is 0)
        - sell_avg: Average sell price in Rupiah (sell_value / sell_volume, decimal string; null when sell_volume is 0)
        - net_value: Net value in Rupiah (buy_value - sell_value; positive = net buy, numeric string)
        - net_volume: Net volume in shares (buy_volume - sell_volume, numeric string)
        - net_freq: Net frequency (buy_freq - sell_freq, numeric string)
        - name: Full broker name (the broker code if unknown)
        
        Update: End of Day (EOD) every day at 18:00 WIB
        
        Limited to data for the last 2 years
        Initial Data: 2016-01-01 [ENTERPRISE]
        
        HTTP: ``GET /analysis/summary/stock/{code}``
        Cache tier: ``default``
        See: https://invezgo.com/id/analysis/summary/stock/BBCA?transaction=true&investor=all
        
        Args:
            code: Kode saham emiten yang tercatat di BEI, mis. `BBCA`. Tidak case-sensitive. Daftar kode tersedia di `/analysis/list/stock`. (path)
            from_: Tanggal awal periode (`YYYY-MM-DD`). Harus lebih kecil atau sama dengan `to`, dengan rentang maksimal 730 hari. (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
            investor: Jenis investor yang dihitung: `all` = seluruh investor, `f` = investor asing, `d` = investor domestik. (required)
            market: Jenis pasar: `RG` = Pasar Reguler, `NG` = Pasar Negosiasi, `TN` = Pasar Tunai. Gunakan `RG` untuk analisis pergerakan harga pada umumnya. (required)
        
        Returns:
            SummaryStockResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/analysis/summary/stock/{code}", path={"code": code}, query={"from": from_, "to": to, "investor": investor, "market": market}, body=None, cache="default")
        return cast("SummaryStockResponse", data)

