    def get_sector_stalker(
        self,
        from_: Union[str, _date],
        to: Union[str, _date],
        *,
        base: Optional[SectorStalkerBase] = None,
        limit: Optional[int] = None,
        filter: Optional[str] = None,
        filter_column: Optional[SectorStalkerFilterColumn] = None,
        filter_operator: Optional[SectorStalkerFilterOperator] = None,
        filter_value: Optional[float] = None,
    ) -> SectorStalkerResponse:
        """Sector Stalker.
        
        Get sectoral index or stock price movement data within a specific time range.
        
        Response:
        - index: List of price series, each item contains:
          - index: Index code (base = COMPOSITE: IDXENERGY, IDXBASIC, IDXINDUST, IDXNONCYC, IDXCYCLIC, IDXHEALTH, IDXFINANCE, IDXPROPERT, IDXTECHNO, IDXINFRA, IDXTRANS, COMPOSITE) or stock code (other base: first item is the base index, then its member stocks sorted by highest latest change)
          - data: Daily close-price series, each item contains:
            - date: Date (YYYY-MM-DD)
            - value: Close price normalized to base 100 on the first date (2 decimals)
        
        Stock Filter (only for base other than COMPOSITE):
        You can filter stocks based on stock data values on the last date in the range.
        
        Filter Examples:
        - filter_column=change&filter_operator=>&filter_value=5 → Stocks with change > 5%
        - filter_column=value&filter_operator=>=&filter_value=1000000000 → Stocks with value >= 1 Billion
        - filter_column=volume&filter_operator=>&filter_value=1000000 → Stocks with volume > 1 Million
        - filter_column=foreign&filter_operator=>&filter_value=0 → Stocks with net foreign buy > 0
        
        Update: Every trading day after market close
        
        Limited to data for the last 2 years
        Initial Data: 2010-01-01 [ENTERPRISE]
        
        Notes:
        - When base = COMPOSITE: displays index prices data (default behavior)
        - When base is changed to another index (e.g., IDX30): displays stock prices data from stocks included in that index
        - Data normalized to base 100 to facilitate performance comparison
        
        HTTP: ``GET /analysis/stalker/sector``
        Cache tier: ``realtime``
        
        Args:
            from_: Tanggal awal periode (`YYYY-MM-DD`). Harus lebih kecil atau sama dengan `to`, dengan rentang maksimal 730 hari. (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
            base: Indeks acuan. `COMPOSITE` (IHSG) menampilkan rotasi antar sektor, sedangkan `SYARIAH` (saham syariah, dibandingkan dengan indeks ISSI) atau indeks sektoral IDX-IC (`IDXENERGY`, `IDXFINANCE`, dst.) menampilkan rotasi saham anggota kategori tersebut. `ISSI` diterima sebagai alias `SYARIAH`. Wajib huruf kapital. (optional, default ``COMPOSITE``)
            limit: Jumlah saham maksimal yang ditampilkan. Hanya berlaku jika `base` bukan `COMPOSITE`. (optional, min ``1``, max ``100``)
            filter: Pencarian saham berdasarkan sebagian kode atau nama, mis. `BB` atau `BANK`. Hanya berlaku jika `base` bukan `COMPOSITE`. (optional)
            filter_column: Kolom yang difilter: `change` = perubahan harga (%), `value` = nilai transaksi, `volume` = volume, `foreign` = net asing, `freq` = frekuensi, `bdm` = aliran dana bandar, `ritel` = aliran dana ritel, `ratio` = rasio, `open`/`high`/`low`/`close` = harga OHLC. Filter aktif hanya jika `filter_column`, `filter_operator`, dan `filter_value` dikirim bersamaan. (optional)
            filter_operator: Operator pembanding untuk filter. Contoh: `filter_column=change&filter_operator=>&filter_value=5` menampilkan saham yang naik lebih dari 5%. (optional)
            filter_value: Nilai pembanding untuk filter. Mendukung bilangan desimal dan negatif, mis. `5` atau `-2.5`. (optional)
        
        Returns:
            SectorStalkerResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/analysis/stalker/sector", path=None, query={"from": from_, "to": to, "base": base, "limit": limit, "filter": filter, "filter_column": filter_column, "filter_operator": filter_operator, "filter_value": filter_value}, body=None, cache="realtime")
        return cast("SectorStalkerResponse", data)

    def get_sector_rotation(
        self,
        from_: Union[str, _date],
        to: Union[str, _date],
        *,
        base: Optional[SectorRotationBase] = None,
        length: Optional[int] = None,
        interval: Optional[SectorRotationInterval] = None,
        tail: Optional[int] = None,
        limit: Optional[int] = None,
        filter: Optional[str] = None,
        filter_column: Optional[SectorRotationFilterColumn] = None,
        filter_operator: Optional[SectorRotationFilterOperator] = None,
        filter_value: Optional[float] = None,
    ) -> SectorRotationResponse:
        """Sector Rotation Chart.
        
        Get sector rotation data for visualizing relative movement of sectoral indices or stocks.
        
        Response:
        - benchmark: Benchmark index code (the base parameter, default COMPOSITE; ISSI when base = SYARIAH)
        - lastDate: Date of the first item's last trail point (YYYY-MM-DD); equals the to parameter when data is empty
        - data: List of sector indices (base = COMPOSITE) or member stocks of base (other base, max limit, default 20), each item contains:
          - code: Sector index code or stock code
          - name: Sector name (e.g. Energy, Financials) or company name
          - trail: Latest movement points (max tail points, daily or weekly per interval), each item contains:
            - date: Point date (YYYY-MM-DD)
            - x: RS-Ratio, relative strength vs the benchmark normalized around 100 (range 60-140, 2 decimals)
            - y: RS-Momentum, rate of change of RS-Ratio normalized around 100 (range 60-140, 2 decimals)
          - quadrant: Quadrant of the last point: leading (x>=100, y>=100), weakening (x>=100, y<100), lagging (x<100, y<100), improving (x<100, y>=100)
        
        Stock Filter (only for base other than COMPOSITE):
        You can filter stocks based on stock data values on the last date in the range.
        
        Filter Examples:
        - filter_column=change&filter_operator=>&filter_value=5 → Stocks with change > 5%
        - filter_column=value&filter_operator=>=&filter_value=1000000000 → Stocks with value >= 1 Billion
        - filter_column=volume&filter_operator=>&filter_value=1000000 → Stocks with volume > 1 Million
        - filter_column=foreign&filter_operator=>&filter_value=0 → Stocks with net foreign buy > 0
        
        Update: Every trading day after market close
        
        Limited to data for the last 2 years
        Initial Data: 2010-01-01 [ENTERPRISE]
        
        Notes:
        - When base = COMPOSITE: displays sectoral index data
        - When base is changed to another index (e.g., IDX30): displays stock data from that index
        
        HTTP: ``GET /analysis/sector/rotation``
        Cache tier: ``realtime``
        
        Args:
            from_: Tanggal awal periode (`YYYY-MM-DD`). Harus lebih kecil atau sama dengan `to`, dengan rentang maksimal 730 hari. (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
            base: Indeks acuan. `COMPOSITE` (IHSG) menampilkan rotasi antar sektor, sedangkan `SYARIAH` (saham syariah, dibandingkan dengan indeks ISSI) atau indeks sektoral IDX-IC (`IDXENERGY`, `IDXFINANCE`, dst.) menampilkan rotasi saham anggota kategori tersebut. `ISSI` diterima sebagai alias `SYARIAH`. Wajib huruf kapital. (optional, default ``COMPOSITE``)
            length: Periode smoothing untuk menghitung RS-Ratio dan RS-Momentum. Nilai kecil lebih responsif, nilai besar lebih halus. (optional, default ``10``, min ``5``, max ``50``)
            interval: Interval data pada Relative Rotation Graph (RRG): `daily` = harian, `weekly` = mingguan. (optional, default ``weekly``)
            tail: Jumlah titik jejak (tail) per sektor atau saham untuk menunjukkan arah pergerakan. (optional, default ``5``, min ``1``, max ``52``)
            limit: Jumlah saham maksimal yang ditampilkan. Hanya berlaku jika `base` bukan `COMPOSITE`. (optional, min ``1``, max ``50``)
            filter: Pencarian saham berdasarkan sebagian kode atau nama, mis. `BB` atau `BANK`. Hanya berlaku jika `base` bukan `COMPOSITE`. (optional)
            filter_column: Kolom yang difilter: `change` = perubahan harga (%), `value` = nilai transaksi, `volume` = volume, `foreign` = net asing, `freq` = frekuensi, `bdm` = aliran dana bandar, `ritel` = aliran dana ritel, `ratio` = rasio, `open`/`high`/`low`/`close` = harga OHLC. Filter aktif hanya jika `filter_column`, `filter_operator`, dan `filter_value` dikirim bersamaan. (optional)
            filter_operator: Operator pembanding untuk filter. Contoh: `filter_column=change&filter_operator=>&filter_value=5` menampilkan saham yang naik lebih dari 5%. (optional)
            filter_value: Nilai pembanding untuk filter. Mendukung bilangan desimal dan negatif, mis. `5` atau `-2.5`. (optional)
        
        Returns:
            SectorRotationResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/analysis/sector/rotation", path=None, query={"from": from_, "to": to, "base": base, "length": length, "interval": interval, "tail": tail, "limit": limit, "filter": filter, "filter_column": filter_column, "filter_operator": filter_operator, "filter_value": filter_value}, body=None, cache="realtime")
        return cast("SectorRotationResponse", data)

    def get_broker_stalker(
        self,
        broker: str,
        stock: str,
        from_: Union[str, _date],
        to: Union[str, _date],
        investor: BrokerStalkerInvestor,
        market: BrokerStalkerMarket,
    ) -> BrokerStalkerResponse:
        """Stock Broker Stalker.
        
        Track a specific broker's trading activity on a specific stock in daily calendar format.
        
        Response:
        - brokers: Tracked broker codes, sorted and comma-joined (e.g. AG,AK)
        - stock: Stock code
        - summary: Period summary, contains:
          - active: Number of days with non-zero net value
          - total: Accumulated net value over the whole period in Rupiah
          - avg: Average net value per active day in Rupiah (total / active; 0 when there are no active days)
          - peak: Day with the highest net buy, contains:
            - date: Date (YYYY-MM-DD); null when no day has a positive net value
            - value: Highest net value in Rupiah (0 when none)
        - calendar: Daily data (only days with broker transactions, ascending date), each item contains:
          - date: Date (YYYY-MM-DD)
          - value: Daily net value in Rupiah (positive = net buy)
          - buy_value: Buy value in Rupiah
          - sell_value: Sell value in Rupiah
          - volume: Net volume in shares
          - buy_volume: Buy volume in shares
          - sell_volume: Sell volume in shares
          - buy_dom: Buy dominance in percent (buy_value / (buy_value + sell_value) x 100, 1 decimal)
          - avg_buy: Average buy price in Rupiah (2 decimals; 0 when there is no buy)
          - avg_sell: Average sell price in Rupiah (2 decimals; 0 when there is no sell)
          - avg_net: Average net price in Rupiah (|net value| / |net volume|, 2 decimals; 0 when net volume is 0)
        
        Update: End of Day (EOD) every day at 18:00 WIB
        
        Limited to data for the last 2 years
        Initial Data: 2016-01-01 [ENTERPRISE]
        
        HTTP: ``GET /analysis/stalker/broker/{broker}/{stock}``
        Cache tier: ``default``
        See: https://invezgo.com/id/analysis/summary/broker/AG
        
        Args:
            broker: Kode broker anggota bursa (2 huruf), mis. `AK`. Dapat berisi beberapa kode yang dipisahkan koma, mis. `AK,BK,YP`. Daftar broker tersedia di `/analysis/list/broker`. Kode yang tidak terdiri dari 2 karakter akan diabaikan. (path)
            stock: Kode saham emiten yang tercatat di BEI, mis. `BBCA`. Tidak case-sensitive. Daftar kode tersedia di `/analysis/list/stock`. (path)
            from_: Tanggal awal periode (`YYYY-MM-DD`). Harus lebih kecil atau sama dengan `to`, dengan rentang maksimal 730 hari. (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
            investor: Jenis investor yang dihitung: `all` = seluruh investor, `f` = investor asing, `d` = investor domestik. (required)
            market: Jenis pasar: `RG` = Pasar Reguler, `NG` = Pasar Negosiasi, `TN` = Pasar Tunai. Gunakan `RG` untuk analisis pergerakan harga pada umumnya. (required)
        
        Returns:
            BrokerStalkerResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/analysis/stalker/broker/{broker}/{stock}", path={"broker": broker, "stock": stock}, query={"from": from_, "to": to, "investor": investor, "market": market}, body=None, cache="default")
        return cast("BrokerStalkerResponse", data)

