class BatchResource:
    """Batch endpoints: fetch many stocks in one request (counted as 1 request)."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def get_order_book(
        self,
        code: str,
        *,
        market: Optional[BatchOrderBookMarket] = None,
        date: Optional[Union[str, _date]] = None,
        time: Optional[str] = None,
    ) -> BatchOrderBookResponse:
        """Batch Stock Order Book.
        
        Get order book data for multiple stocks at once in a single request (up to 10 codes on the MAX plan, 25 on the ELITE plan).
        
        Data Retrieval Modes:
        - Realtime: Without date/time parameters - uses realtime data; falls back to the latest data when it is not available yet
        - Historical: With date and time parameters - retrieves order book data at that exact minute (WIB); bid and offer are empty when there is none
        
        Response (array, one item per code):
        - code: Stock code (with the market suffix when market is not RG, e.g. BBCANG)
        - bid: List of buy queue levels, ordered from level 1 (best price); each item's keys use the level number n:
          - bid<n>price: Bid price at level n (Rupiah)
          - bid<n>lot: Number of lots at level n
          - bid<n>freq: Number of orders at level n
        - offer: List of sell queue levels, ordered from level 1 (best price); each item's keys use the level number n:
          - offer<n>price: Offer price at level n (Rupiah)
          - offer<n>lot: Number of lots at level n
          - offer<n>freq: Number of orders at level n
        
        Historical Parameters:
        - date: Date in YYYY-MM-DD format (optional, data available from 2026-03-25)
        - time: WIB time in HH:MM format with minute precision (optional)
        - Note: fill date and time together for historical data; when only one is filled, the latest data is used
        
        Access & Limits:
        - API Key only, on the MAX or ELITE plans
        - Codes per request: up to 10 on the MAX plan, 25 on the ELITE plan
        
        Update: Real-time (without date/time) or Historical (with date/time)
        
        HTTP: ``GET /batch/order-book/{code}``
        Cache tier: ``realtime``
        
        Args:
            code: Daftar kode saham yang dipisahkan `|` atau koma, mis. `BBCA|GOTO|TLKM`. Maksimal 10 kode (paket MAX) atau 25 kode (paket ELITE) per request. (path)
            market: Jenis pasar: `RG` = Pasar Reguler, `NG` = Pasar Negosiasi, `TN` = Pasar Tunai. Gunakan `RG` untuk analisis pergerakan harga pada umumnya. Default `RG` bila tidak diisi. (optional, default ``RG``)
            date: Tanggal order book historis (`YYYY-MM-DD`), data tersedia mulai `2026-03-25`. Kirim bersama `time`; kosongkan keduanya untuk data realtime. (optional)
            time: Jam order book dalam WIB, format `HH:mm` dengan presisi menit. Kirim bersama `date`. (optional)
        
        Returns:
            BatchOrderBookResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/batch/order-book/{code}", path={"code": code}, query={"market": market, "date": date, "time": time}, body=None, cache="realtime")
        return cast("BatchOrderBookResponse", data)

    def get_intraday_data(
        self,
        code: str,
        *,
        market: Optional[BatchIntradayDataMarket] = None,
        date: Optional[Union[str, _date]] = None,
    ) -> BatchIntradayDataResponse:
        """Batch Stock Intraday Data.
        
        Get compact intraday price data for multiple stocks at once in a single request (up to 10 codes on the MAX plan, 25 on the ELITE plan).
        
        Data Retrieval Modes:
        - Realtime: Without the date parameter - uses realtime data (fields that are not available are omitted); falls back to the latest daily data when it is not available yet
        - Historical: With the date parameter - retrieves daily data on that date
        - Note: in daily data, avg, prev, bid_*, offer_*, iep and iev are null
        
        Response (array, one item per code):
        - code: Stock code (with the market suffix when market is not RG)
        - open: Opening price (Rupiah)
        - high: Highest price (Rupiah)
        - low: Lowest price (Rupiah)
        - close: Last/closing price (Rupiah)
        - avg: Average price (Rupiah)
        - volume: Trading volume (shares)
        - freq: Trade frequency (count)
        - value: Trading value (Rupiah)
        - prev: Previous trading day's closing price (Rupiah)
        - bid_price: Best bid price (Rupiah)
        - bid_lot: Queued volume at the best bid
        - bid_freq: Number of orders at the best bid
        - offer_price: Best offer price (Rupiah)
        - offer_lot: Queued volume at the best offer
        - offer_freq: Number of orders at the best offer
        - iep: Indicative Equilibrium Price during pre-opening/pre-closing (Rupiah)
        - iev: Indicative Equilibrium Volume during pre-opening/pre-closing
        
        Access & Limits:
        - API Key only, on the MAX or ELITE plans
        - Codes per request: up to 10 on the MAX plan, 25 on the ELITE plan
        
        Notes:
        - A code without data contains only code and close (null)
        
        Update: Real-time (without date) or Historical (with date)
        
        HTTP: ``GET /batch/intraday-data/{code}``
        Cache tier: ``realtime``
        
        Args:
            code: Daftar kode saham yang dipisahkan `|` atau koma, mis. `BBCA|GOTO|TLKM`. Maksimal 10 kode (paket MAX) atau 25 kode (paket ELITE) per request. (path)
            market: Jenis pasar: `RG` = Pasar Reguler, `NG` = Pasar Negosiasi, `TN` = Pasar Tunai. Gunakan `RG` untuk analisis pergerakan harga pada umumnya. Default `RG` bila tidak diisi. (optional, default ``RG``)
            date: Tanggal data historis (`YYYY-MM-DD`). Kosongkan untuk data realtime hari ini. (optional)
        
        Returns:
            BatchIntradayDataResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/batch/intraday-data/{code}", path={"code": code}, query={"market": market, "date": date}, body=None, cache="realtime")
        return cast("BatchIntradayDataResponse", data)

    def get_intraday_index(
        self,
        code: str,
    ) -> BatchIntradayIndexResponse:
        """Batch Index Intraday Data.
        
        Get compact intraday data for multiple indexes at once in a single request (up to 10 codes on the MAX plan, 25 on the ELITE plan).
        
        Data Retrieval Modes:
        - Realtime: When realtime data is available - uses realtime data (fields that are not available are omitted)
        - Latest: When realtime data is not available yet - uses the latest trading day's daily data; prev is null, positive/negative/neutral/suspend are 0 and market_value equals value
        
        Response (array, one item per code):
        - code: Index code
        - open: Index opening value
        - high: Index highest value
        - low: Index lowest value
        - close: Index last/closing value
        - volume: Trading volume (shares)
        - freq: Trade frequency (count)
        - value: Trading value (Rupiah)
        - prev: Index closing value on the previous trading day
        - positive: Number of advancing stocks
        - negative: Number of declining stocks
        - neutral: Number of unchanged stocks
        - suspend: Number of untraded/suspended stocks
        - market_cap: Market capitalization (Rupiah)
        - market_value: Market value (Rupiah)
        
        Access & Limits:
        - API Key only, on the MAX or ELITE plans
        - Codes per request: up to 10 on the MAX plan, 25 on the ELITE plan
        
        Notes:
        - A code without data contains only code and close (null)
        
        Update: Real-time
        
        HTTP: ``GET /batch/intraday-index/{code}``
        Cache tier: ``realtime``
        
        Args:
            code: Daftar kode indeks yang dipisahkan `|` atau koma, mis. `COMPOSITE|LQ45|IDX30`. Maksimal 10 kode (paket MAX) atau 25 kode (paket ELITE) per request. Daftar indeks tersedia di `/analysis/list/index`. (path)
        
        Returns:
            BatchIntradayIndexResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/batch/intraday-index/{code}", path={"code": code}, query=None, body=None, cache="realtime")
        return cast("BatchIntradayIndexResponse", data)


class SearchResource:
    """Search stocks and users."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def search(
        self,
        query: str,
    ) -> SearchResponse:
        """Search Stock or User.
        
        Search for stocks or users simultaneously based on query keywords.
        
        Response:
        - results: Search results per index (order: user_lists then stock_lists), each item contains:
          - indexUid: Search index name: user_lists or stock_lists
          - hits: Matches (max 5 for user_lists, max 10 for stock_lists), each item contains:
            - username / name / image: For user_lists: username, display name and profile picture URL (null if none)
            - code / name / logo: For stock_lists: stock code, company name and company icon URL
          - query: Searched keyword
          - processingTimeMs: Search processing time (milliseconds)
          - limit: Result limit for this index
          - offset: Result offset (always 0)
          - estimatedTotalHits: Estimated total number of matches
          - requestUid: Unique search request ID
        
        Update: Real-time
        
        HTTP: ``GET /search``
        Cache tier: ``default``
        
        Args:
            query: Kata kunci pencarian berupa kode saham, nama perusahaan, atau username. (required)
        
        Returns:
            SearchResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/search", path=None, query={"query": query}, body=None, cache="default")
        return cast("SearchResponse", data)

    def search_stock(
        self,
        query: str,
        *,
        cursor: Optional[int] = None,
    ) -> SearchStockResponse:
        """Search Stock only.
        
        Search for stock data listed on the Indonesia Stock Exchange (IDX) based on query keywords with pagination support.
        
        Response:
        - hits: Matching stocks (max 20 per page), each item contains:
          - code: Stock code
          - name: Company name
          - logo: Company icon image URL
        - query: Searched keyword
        - processingTimeMs: Search processing time (milliseconds)
        - hitsPerPage: Results per page (always 20)
        - page: Current page number (from the cursor parameter, default 1)
        - totalPages: Total number of pages
        - totalHits: Total number of matches
        
        Update: Real-time (synced with IDX stock list)
        
        HTTP: ``GET /search/stock``
        Cache tier: ``default``
        
        Args:
            query: Kata kunci pencarian berupa kode saham atau nama perusahaan. (required)
            cursor: Nomor halaman hasil pencarian, dimulai dari 1. Setiap halaman berisi 20 hasil. (optional, default ``1``, min ``1``)
        
        Returns:
            SearchStockResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/search/stock", path=None, query={"query": query, "cursor": cursor}, body=None, cache="default")
        return cast("SearchStockResponse", data)

    def search_user(
        self,
        query: str,
        *,
        cursor: Optional[int] = None,
    ) -> SearchUserResponse:
        """Search User only.
        
        Search for Invezgo app users based on query keywords with pagination support.
        
        Response:
        - hits: Matching users (max 20 per page), each item contains:
          - username: User's username
          - name: User's display name
          - image: User's profile picture URL (null if none)
        - query: Searched keyword
        - processingTimeMs: Search processing time (milliseconds)
        - hitsPerPage: Results per page (always 20)
        - page: Current page number (from the cursor parameter, default 1)
        - totalPages: Total number of pages
        - totalHits: Total number of matches
        
        Update: Real-time
        
        HTTP: ``GET /search/user``
        Cache tier: ``default``
        
        Args:
            query: Kata kunci pencarian berupa username atau nama pengguna. (required)
            cursor: Nomor halaman hasil pencarian, dimulai dari 1. Setiap halaman berisi 20 hasil. (optional, default ``1``, min ``1``)
        
        Returns:
            SearchUserResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/search/user", path=None, query={"query": query, "cursor": cursor}, body=None, cache="default")
        return cast("SearchUserResponse", data)


class ScreenerResource:
    """Run stock screeners and manage saved screener presets."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def screen(
        self,
        body: ScreenRequest,
    ) -> ScreenerScreenResponse:
        """Screener.
        
        Get a list of stock data matching the specified formula.
        
        Update: Real-time (for real-time variables) and EOD (for non-real-time variables)
        
        Rate Limit: This endpoint has a special rate limit of 1 request per minute.
        
        Response:
        - code: Stock code matching the formula (max 1200 stocks)
        - matched: Formula match status, always true (only matching stocks are returned)
        - <variable>: Value of each non-numeric expression on either side of a formula comparison, key = the exact expression text (e.g. close, prev, rsi(14), (volume/100)); number rounded to 6 decimals, null if it cannot be evaluated
        
        HTTP: ``POST /screener/screen``
        Cache tier: ``none``
        See: https://invezgo.com/screener
        
        Args:
            body: Payload untuk menjalankan screener
        
        Returns:
            ScreenerScreenResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("POST", "/screener/screen", path=None, query=None, body=body, cache="none")
        return cast("ScreenerScreenResponse", data)

    def list(
        self,
    ) -> ScreenerListResponse:
        """Screener Preset List.
        
        Get the list of screener presets, grouped into your own presets, public presets, and presets shared with your plan.
        
        Response:
        - name: Group name: Private (your own presets), Public (presets with public scope), Membership (presets shared with your plan)
        - groups: Presets in the group, each item contains:
          - id: Preset ID (only in the Private group), used for PUT/DELETE /screener/{id}
          - name: Preset name
          - description: Preset description (null if empty)
          - scope: Preset visibility list (e.g. ["public"] or plan names)
          - formula: Screener formula, can be run with POST /screener/screen
          - category: Index categories the stocks are filtered to (e.g. ["SYARIAH"]); empty or null means all stocks
          - profile_name: Name of the preset creator
          - profile_image: Profile picture URL of the preset creator (null if none)
        
        Notes:
        - The response always contains three groups in the order Private, Public, Membership
        - Changes to other users' presets may appear up to 2 hours late; changes to your own presets are visible immediately
        
        HTTP: ``GET /screener``
        Cache tier: ``default``
        
        Returns:
            ScreenerListResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/screener", path=None, query=None, body=None, cache="default")
        return cast("ScreenerListResponse", data)

    def save(
        self,
        body: SaveScreenerRequest,
    ) -> ScreenerSaveResponse:
        """Save Screener Preset.
        
        Save a new screener preset. The formula is tested first; if it is invalid, the preset is not saved and the 400 response contains the formula error details.
        
        Response:
        - message: Success message in the requested language (Accept-Language), e.g. "New preset {name} added successfully"
        
        Notes:
        - scope defaults to ["public"] when omitted
        - an omitted category means all stocks
        - the new preset ID is listed in the Private group of GET /screener
        
        HTTP: ``POST /screener``
        Cache tier: ``none``
        
        Args:
            body: Request body.
        
        Returns:
            ScreenerSaveResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("POST", "/screener", path=None, query=None, body=body, cache="none")
        return cast("ScreenerSaveResponse", data)

    def update(
        self,
        id: str,
        body: UpdateScreenerRequest,
    ) -> ScreenerUpdateResponse:
        """Update Screener Preset.
        
        Update one of your screener presets by ID. All fields (name, description, scope, formula, category) are overwritten with the new values, and the formula is tested first.
        
        Response:
        - message: Success message in the requested language (Accept-Language), e.g. "Preset {name} updated successfully"
        
        Notes:
        - scope defaults to ["public"] when omitted; an omitted description or category is cleared
        - an ID that does not exist or is not yours changes nothing but still returns the success message
        
        HTTP: ``PUT /screener/{id}``
        Cache tier: ``none``
        
        Args:
            id: ID preset screener, diambil dari field `id` pada response `GET /screener`. (path)
            body: Request body.
        
        Returns:
            ScreenerUpdateResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("PUT", "/screener/{id}", path={"id": id}, query=None, body=body, cache="none")
        return cast("ScreenerUpdateResponse", data)

    def delete(
        self,
        id: str,
    ) -> ScreenerDeleteResponse:
        """Delete Screener Preset.
        
        Delete one of your screener presets by ID.
        
        Response:
        - message: Success message in the requested language (Accept-Language), e.g. "Preset {name} deleted successfully"
        
        HTTP: ``DELETE /screener/{id}``
        Cache tier: ``none``
        
        Args:
            id: ID preset screener, diambil dari field `id` pada response `GET /screener`. (path)
        
        Returns:
            ScreenerDeleteResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("DELETE", "/screener/{id}", path={"id": id}, query=None, body=None, cache="none")
        return cast("ScreenerDeleteResponse", data)


class UsageResource:
    """API usage and quota monitoring (does not consume quota)."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def get_api_usage(
        self,
    ) -> ApiUsageResponse:
        """API Usage.
        
        Information on API usage.
        
        Response:
        - usage: Number of requests counted in the current quota period
        - remaining: Requests left in the quota period (minimum 0; in-flight requests are also deducted)
        - limit: Monthly request quota of the plan
        - isBlocked: true when the quota is used up
        - expire: Quota reset time (DateTime WIB (UTC+7), e.g. 2026-10-16T00:00:00.000Z = 16 Oct 2026 00:00 WIB; the Z suffix does not mean UTC, do not convert the time zone)
        - role: Active plan name in upper case, e.g. ADVANCE
        
        Notes:
        - The quota period is 30 days, or until the subscription ends if that is sooner
        - Calling this endpoint does not consume quota
        
        HTTP: ``GET /usage/api``
        Cache tier: ``none``
        
        Returns:
            ApiUsageResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/usage/api", path=None, query=None, body=None, cache="none")
        return cast("ApiUsageResponse", data)

    def get_logs(
        self,
        *,
        from_: Optional[str] = None,
        to: Optional[str] = None,
        status: Optional[int] = None,
        limit: Optional[int] = None,
    ) -> UsageLogsResponse:
        """API Usage Logs.
        
        Get the API usage log history (requests made with an API key) of the authenticated user, newest first.
        
        Response:
        - id: Log ID
        - date: Request time (ISO 8601 with a time-zone offset, e.g. 2026-07-30T22:57:26.606+07:00)
        - method: HTTP method
        - url: Called endpoint URL
        - access: Client User-Agent
        - status: HTTP status code of the response
        - response_time: Response time in milliseconds
        
        Notes:
        - from cannot be more than 30 days ago (counted from the start of that day, WIB); defaults to the last 24 hours
        - to defaults to the current time and cannot be earlier than from
        - Without limit, all logs in the time range are returned
        - Calling this endpoint does not consume quota
        
        HTTP: ``GET /usage/logs``
        Cache tier: ``none``
        
        Args:
            from_: Waktu awal dalam WIB, format `YYYY-MM-DD HH:mm:ss` atau `YYYY-MM-DD`. Maksimal 30 hari ke belakang. Default 24 jam terakhir. (optional)
            to: Waktu akhir dalam WIB, format `YYYY-MM-DD HH:mm:ss` atau `YYYY-MM-DD`. Harus lebih besar atau sama dengan `from`. Default waktu saat ini. (optional)
            status: Filter log berdasarkan HTTP status code, mis. `200`, `422`, atau `429`. (optional, min ``100``, max ``599``)
            limit: Jumlah log maksimal yang dikembalikan. Kosongkan untuk mengambil seluruh log. (optional, min ``1``, max ``320000``)
        
        Returns:
            UsageLogsResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/usage/logs", path=None, query={"from": from_, "to": to, "status": status, "limit": limit}, body=None, cache="none")
        return cast("UsageLogsResponse", data)


class WatchlistsResource:
    """Personal watchlists and watchlist groups."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def list(
        self,
        *,
        group: Optional[str] = None,
    ) -> WatchlistsListResponse:
        """Watchlist.
        
        Get the stocks in the user's watchlist with their last price and percentage change against the saved reference price.
        
        Response:
        - id: Watchlist item ID (used by `PUT /watchlists/{id}`, `PATCH /watchlists/{id}` and `DELETE /watchlists`)
        - code: Stock code
        - note: User note (null if none)
        - price: Reference price saved by the user (Rupiah)
        - name: Company name (null if the code is not in the stock list)
        - last: Last price (Rupiah), null if no price data yet
        - change: Percentage change of `last` against `price` (%), null if no price data yet
        - group_id: Watchlist group ID (null if the item has no group)
        
        Update: Between 08:40 and 18:30 WIB, `last` and `change` use the realtime price when available; outside those hours they use the latest closing price.
        
        Notes:
        - Set `group` to an ID from the `value` field of `GET /watchlists/group` to show one group; set it to `null` (or omit it) to show the whole watchlist across all groups.
        - Order: most recently updated items first.
        - `last` and `change` may be delayed, so they do not always reflect the current price; adding, updating or deleting a watchlist item reloads the data.
        
        HTTP: ``GET /watchlists``
        Cache tier: ``default``
        
        Args:
            group: ID grup watchlist yang ingin ditampilkan, diambil dari field `id` pada response `GET /watchlists/group`. Kosongkan atau isi `null` untuk menampilkan seluruh watchlist dari semua grup. (optional)
        
        Returns:
            WatchlistsListResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/watchlists", path=None, query={"group": group}, body=None, cache="default")
        return cast("WatchlistsListResponse", data)

    def add(
        self,
        body: AddWatchlistRequest,
    ) -> WatchlistsAddResponse:
        """Add Stock to Watchlist.
        
        Add a new stock to the user's watchlist.
        
        Response:
        - message: Confirmation message, e.g. "BBCA added to watchlist"
        
        Notes:
        - group: Group ID from the `value` field of `GET /watchlists/group` (exactly 25 characters).
        - code: Stock code (max 6 characters).
        - price: Reference price in Rupiah (at least 1), used to compute `change` in `GET /watchlists`.
        - note: Optional note (max 150 characters); do not send null, omit the field instead.
        - scope: Array of visibility strings for the watchlist item.
        - A stock code can appear only once across the user's whole watchlist; adding an existing code returns `409`.
        - `group` must be an existing group ID and `code` a listed stock code; otherwise the request fails.
        
        HTTP: ``POST /watchlists``
        Cache tier: ``none``
        
        Args:
            body: Request body.
        
        Returns:
            WatchlistsAddResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("POST", "/watchlists", path=None, query=None, body=body, cache="none")
        return cast("WatchlistsAddResponse", data)

    def delete(
        self,
        body: DeleteIdsRequest,
    ) -> WatchlistsDeleteResponse:
        """Delete Watchlist Items.
        
        Delete one or more stocks from the user's watchlist by item ID.
        
        Response:
        - message: Confirmation message with the number of IDs sent, e.g. "2 watchlist deleted"
        
        Notes:
        - Send a JSON body `{"id": ["<id>", ...]}` with IDs from the `id` field of `GET /watchlists`.
        - The number in the message is the length of the `id` array sent, not the number of items actually deleted; IDs that are not found or belong to another user are ignored.
        - `id` must be an array.
        
        HTTP: ``DELETE /watchlists``
        Cache tier: ``none``
        
        Args:
            body: Daftar ID item watchlist yang akan dihapus.
        
        Returns:
            WatchlistsDeleteResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("DELETE", "/watchlists", path=None, query=None, body=body, cache="none")
        return cast("WatchlistsDeleteResponse", data)

    def list_groups(
        self,
    ) -> WatchlistsListGroupsResponse:
        """Watchlist Group List.
        
        Get the user's watchlist groups.
        
        Response:
        - value: Watchlist group ID (used as `group` in `GET /watchlists`, `POST /watchlists`, `PUT /watchlists/{id}`, and as `{id}` in `PUT`/`DELETE /watchlists/group/{id}`)
        - label: Group name
        
        Notes:
        - Returns an empty array if the user has no groups.
        - Group order is not guaranteed.
        
        HTTP: ``GET /watchlists/group``
        Cache tier: ``default``
        
        Returns:
            WatchlistsListGroupsResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/watchlists/group", path=None, query=None, body=None, cache="default")
        return cast("WatchlistsListGroupsResponse", data)

    def add_group(
        self,
        body: WatchlistGroupRequest,
    ) -> WatchlistsAddGroupResponse:
        """Create Watchlist Group.
        
        Create a new watchlist group for the user.
        
        Response:
        - message: Confirmation message, "Group added"
        
        Notes:
        - name: Group name (1-100 characters).
        - The new group's ID is available in the `value` field of `GET /watchlists/group`.
        
        HTTP: ``POST /watchlists/group``
        Cache tier: ``none``
        
        Args:
            body: Request body.
        
        Returns:
            WatchlistsAddGroupResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
