class TradesResource:
    """Personal realized trades."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def list(
        self,
        from_: Union[str, _date],
        to: Union[str, _date],
    ) -> TradesListResponse:
        """Realized Trade List.
        
        Get the user's realized trades (from SELL journal entries) with a sell date between `from` and `to` (inclusive), newest first.
        
        Response:
        - id: Realized trade ID (used by `PATCH /trades/{id}` and `DELETE /trades`)
        - code: Stock code
        - broker: Broker code (2 letters)
        - date: Sell date (WIB (UTC+7) DateTime, e.g. 2026-10-16T00:00:00.000Z = 16 Oct 2026 00:00 WIB; the Z suffix does not mean UTC, do not convert the time zone)
        - lot: Sold lots (1 lot = 100 shares)
        - buy_price: Average buy price per share at the time of the sale, incl. buy fee (Rupiah)
        - sell_price: Sell price per share (Rupiah)
        - buy_value: Buy value = lot x 100 x buy_price, rounded (Rupiah)
        - sell_value: Sell value = lot x 100 x sell_price, before sell fee (Rupiah)
        - net: Net profit/loss = sell_value - sell fee - buy_value, rounded (Rupiah)
        - percent: Price gain/loss = (sell_price - buy_price) / buy_price x 100, 4 decimals (%)
        - status: PROFIT, LOSS or BEP based on net
        - note: User note, null if empty
        
        HTTP: ``GET /trades``
        Cache tier: ``default``
        
        Args:
            from_: Tanggal awal periode (`YYYY-MM-DD`). (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
        
        Returns:
            TradesListResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/trades", path=None, query={"from": from_, "to": to}, body=None, cache="default")
        return cast("TradesListResponse", data)

    def delete(
        self,
        body: DeleteIdsRequest,
    ) -> TradesDeleteResponse:
        """Delete Realized Trades.
        
        Delete one or more realized trades by ID (body `{"id": ["<id>", ...]}`). Only the realized-trade records are removed; journal transactions and the portfolio are unchanged.
        
        Response:
        - message: Confirmation message
        
        Note: IDs come from the `id` field of `GET /trades`; unknown IDs are ignored.
        
        HTTP: ``DELETE /trades``
        Cache tier: ``none``
        
        Args:
            body: Daftar ID transaksi terealisasi yang akan dihapus.
        
        Returns:
            TradesDeleteResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("DELETE", "/trades", path=None, query=None, body=body, cache="none")
        return cast("TradesDeleteResponse", data)

    def get_summary(
        self,
        from_: Union[str, _date],
        to: Union[str, _date],
    ) -> TradesSummaryResponse:
        """Realized Trade Summary.
        
        Get a performance summary of the user's realized trades with a sell date between `from` and `to` (inclusive): profit/loss/BEP counts, totals, win rate, and the best and worst trades.
        
        Response:
        - top_code: Stock codes, most trades first
        - total_transaction: Number of realized trades in the period
        - total_profit: Number of PROFIT trades
        - total_loss: Number of LOSS trades
        - total_bep: Number of BEP (break-even) trades
        - total_buy_value: Total buy value (Rupiah)
        - total_sell_value: Total sell value (Rupiah)
        - total_net: Total net profit/loss (Rupiah)
        - win_rate: Share of PROFIT trades (%)
        - loss_rate: Share of LOSS trades (%)
        - bep_rate: Share of BEP trades (%)
        - top_win_value: PROFIT trade with the largest net, contains:
          - code: Stock code (empty string if none)
          - value: Net value (Rupiah), 0 if none
        - top_loss_value: LOSS trade with the largest net loss, contains code and value (Rupiah)
        - top_win_percent: PROFIT trade with the highest percent, contains code and value (%)
        - top_loss_percent: LOSS trade with the lowest percent, contains code and value (%)
        
        Note: When there are no trades in the period, every number is 0, top_code is empty and each top_* is {"code": "", "value": 0}.
        
        HTTP: ``GET /trades/summary``
        Cache tier: ``default``
        
        Args:
            from_: Tanggal awal periode (`YYYY-MM-DD`). (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
        
        Returns:
            TradesSummaryResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/trades/summary", path=None, query={"from": from_, "to": to}, body=None, cache="default")
        return cast("TradesSummaryResponse", data)

    def get_summary_chart(
        self,
        from_: Union[str, _date],
        to: Union[str, _date],
        code: str,
    ) -> TradesSummaryChartResponse:
        """Realized Trade Summary Chart.
        
        Get daily chart data of the user's realized profit/loss with a sell date between `from` and `to` (inclusive), with its running total and the comparison index close on the same day. Only days with realized trades are returned, in ascending date order.
        
        Response:
        - date: Trade day (YYYY-MM-DD, WIB)
        - net: Net profit/loss on that day, 2 decimals (Rupiah)
        - cumulative_net: Running total of net since the start of the period, 2 decimals (Rupiah)
        - close: Comparison index close on that day, 2 decimals; null if no index data
        
        Notes:
        - The `code` parameter is the comparison index code (e.g. COMPOSITE)
        - When `code` is sent empty (`code=`), a day can appear more than once, one row per index that has data on that day
        
        HTTP: ``GET /trades/summary-chart``
        Cache tier: ``default``
        
        Args:
            from_: Tanggal awal periode (`YYYY-MM-DD`). (required)
            to: Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (required)
            code: Kode indeks pembanding pada grafik, mis. `COMPOSITE`. Bila dikirim kosong (`code=`), setiap tanggal berisi satu baris per indeks. (required)
        
        Returns:
            TradesSummaryChartResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("GET", "/trades/summary-chart", path=None, query={"from": from_, "to": to, "code": code}, body=None, cache="default")
        return cast("TradesSummaryChartResponse", data)

    def update_note(
        self,
        id: str,
        body: NoteTradeRequest,
    ) -> TradesUpdateNoteResponse:
        """Update Realized Trade Note.
        
        Update the note of one of the user's realized trades. Body: `{"note": "..."}` (optional, max 150 characters); when `note` is omitted the note is cleared.
        
        Response:
        - message: Confirmation message
        
        Note: The ID comes from the `id` field of `GET /trades`. An unknown ID does not produce an error.
        
        HTTP: ``PATCH /trades/{id}``
        Cache tier: ``none``
        
        Args:
            id: ID transaksi terealisasi, diambil dari field `id` pada response `GET /trades`. (path)
            body: Request body.
        
        Returns:
            TradesUpdateNoteResponse
        
        Raises:
            InvezgoError: on any API error (see ``invezgo.exceptions``); RateLimitError when every API key is rate limited.
        """
        data = self._t.request("PATCH", "/trades/{id}", path={"id": id}, query=None, body=body, cache="none")
        return cast("TradesUpdateNoteResponse", data)


class ResourcesMixin:
    """Attaches one attribute per API resource."""

    analysis: AnalysisResource
    batch: BatchResource
    search: SearchResource
    screener: ScreenerResource
    usage: UsageResource
    watchlists: WatchlistsResource
    journals: JournalsResource
    portfolios: PortfoliosResource
    alerts: AlertsResource
    posts: PostsResource
    trades: TradesResource

    def _init_resources(self, transport: Transport) -> None:
        self.analysis = AnalysisResource(transport)
        self.batch = BatchResource(transport)
        self.search = SearchResource(transport)
        self.screener = ScreenerResource(transport)
        self.usage = UsageResource(transport)
        self.watchlists = WatchlistsResource(transport)
        self.journals = JournalsResource(transport)
        self.portfolios = PortfoliosResource(transport)
        self.alerts = AlertsResource(transport)
        self.posts = PostsResource(transport)
        self.trades = TradesResource(transport)


__all__ = ["AnalysisResource", "BatchResource", "SearchResource", "ScreenerResource", "UsageResource", "WatchlistsResource", "JournalsResource", "PortfoliosResource", "AlertsResource", "PostsResource", "TradesResource", "ResourcesMixin"]

_ = (Any, Dict, List, Literal, Union, _date)
